import unittest
from candidate import hex_key

class TestHexKey(unittest.TestCase):
    def test_hex_key_empty_string(self):
        self.assertEqual(hex_key(""), 0)

    def test_hex_key_single_prime(self):
        self.assertEqual(hex_key("2"), 1)

    def test_hex_key_single_non_prime(self):
        self.assertEqual(hex_key("1"), 0)

    def test_hex_key_multiple_primes(self):
        self.assertEqual(hex_key("237B"), 4)

    def test_hex_key_multiple_non_primes(self):
        self.assertEqual(hex_key("0468"), 0)

    def test_hex_key_mixed_primes_and_non_primes(self):
        self.assertEqual(hex_key("1077E"), 2)

    def test_hex_key_all_primes(self):
        self.assertEqual(hex_key("23B5D7"), 6)

    def test_hex_key_all_non_primes(self):
        self.assertEqual(hex_key("04689ABCDEF"), 0)

    def test_hex_key_repeated_primes(self):
        self.assertEqual(hex_key("22BBDD"), 6)

    def test_hex_key_repeated_non_primes(self):
        self.assertEqual(hex_key("000011"), 0)

if __name__ == '__main__':
    unittest.main()
